// === Tab: mySketch ===
const NUM = 30;
const cp = [
  "#ffb6b9",
  "#bbded6",
  "#fae3d9",
  "#8ac6d1",
  "#fff1ac",
  "#f9bcdd",
  "#d5a4cf",
  "#b689b0",
];
let stars = [];
let tmpX, tmpY;
let target = 0;
let angle;

function setup() {
  createCanvas(windowWidth, windowHeight);
  textSize(40);
  textAlign(CENTER);

  for (let i = 0; i < NUM; i++) {
    tmpX = random(width);
    tmpY = random(height);
    stars.push({
      x: tmpX,
      y: tmpY,
      middleX: tmpX,
      middleY: tmpY,
      size: random(10, 30),
      ellipseColor: "#fff",
      lineColor: random(cp),
    });
  }
  stars[NUM - 1] = stars[0];
}

function draw() {
  background(0);

  if (target + 1 < NUM) {
    push();
    stroke(stars[target].lineColor);
    strokeWeight(5);
    line(
      stars[target].middleX,
      stars[target].middleY,
      stars[target].x,
      stars[target].y,
    );
    // point(stars[target].middleX, stars[target].middleY);
    push();
    translate(stars[target].middleX, stars[target].middleY);
    angle = atan2(
      stars[target + 1].y - stars[target].middleY,
      stars[target + 1].x - stars[target].middleX,
    );
    rotate(angle + QUARTER_PI);
    text("🚀", 0, 0);
    pop();
    pop();
    stars[target].middleX = lerp(
      stars[target].middleX,
      stars[target + 1].x,
      0.3,
    );
    stars[target].middleY = lerp(
      stars[target].middleY,
      stars[target + 1].y,
      0.3,
    );

    if (
      dist(
        stars[target].middleX,
        stars[target].middleY,
        stars[target + 1].x,
        stars[target + 1].y,
      ) <
      stars[target + 1].size / 2
    ) {
      stars[target].ellipseColor = stars[target].lineColor;
			fill(stars[target].lineColor)
			ellipse(stars[target].x, stars[target].y, 40)
      target++;
    }

    if (target + 1 === NUM) {
      for (let i = 0; i < NUM; i++) {
        stars[i].middleX = stars[i].x;
        stars[i].middleY = stars[i].y;
      }
      target = 0;
    }
  }

	push();
  for (star of stars) {
    noStroke();
    fill(star.ellipseColor);
    drawingContext.shadowBlur = 8;
    drawingContext.shadowColor = star.ellipseColor;
    ellipse(star.x, star.y, star.size, star.size);
  }
  pop();
}

